function f(){async function r(e,s={}){const{timeout:c=15e3,headers:i={},...l}=s,o=new AbortController,m=setTimeout(()=>o.abort(),c);try{const t=await fetch(""+e,{credentials:"include",...l,headers:{"Content-Type":"application/json",...i},signal:o.signal});if(t.status===401)return{error:!0,status:401,message:"请先验证访问权限"};if(!t.ok){let n="请求失败，请稍后重试";try{n=(await t.json()).message||n}catch{}return{error:!0,status:t.status,message:n}}return t.json()}catch(t){return t.name==="AbortError"?{error:!0,status:0,message:"请求超时，请稍后重试"}:{error:!0,status:0,message:"网络连接失败，请检查网络后重试"}}finally{clearTimeout(m)}}async function a(e){return r(e,{method:"GET"})}async function u(e,s){return r(e,{method:"POST",body:JSON.stringify(s)})}return{request:r,get:a,post:u}}export{f as u};
